INSERT INTO exercises (external_id, name, category, body_part, equipment, target, muscle_group, secondary_muscles, instructions_es, gif_url, image_url)
VALUES
  ('0025', 'barbell bench press', 'Pecho', 'chest', 'barbell', 'pectorals', 'Triceps', ARRAY['Triceps', 'shoulders'], 'Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco. Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros. Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos. Baja la barra lentamente hacia el pecho, manteniendo los codos pegados al cuerpo. Haz una pausa breve cuando la barra toque el pecho. Empuja la barra de vuelta a la posición inicial extendiendo los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/0025-EIeI8Vf.gif', '/exercises/images/0025-EIeI8Vf.jpg'),
  ('0289', 'dumbbell bench press', 'Pecho', 'chest', 'dumbbell', 'pectorals', 'Triceps', ARRAY['Triceps', 'shoulders'], 'Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco. Sujeta una mancuerna en cada mano, con las palmas hacia adelante y los brazos extendidos por encima del pecho. Baja lentamente las mancuernas hacia los lados del pecho, manteniendo los codos en un ángulo de 90 grados. Haz una pausa breve, luego empuja las mancuernas de vuelta hacia arriba hasta la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/0289-SpYC0Kp.gif', '/exercises/images/0289-SpYC0Kp.jpg'),
  ('0308', 'dumbbell fly', 'Pecho', 'chest', 'dumbbell', 'pectorals', 'shoulders', ARRAY['shoulders'], 'Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí. Extiende los brazos rectos hacia arriba sobre el pecho, con una ligera flexión en los codos. Manteniendo una ligera flexión en los codos, baja los brazos hacia los lados en un amplio arco hasta sentir un estiramiento en el pecho. Haz una pausa por un momento, luego invierte el movimiento y lleva las mancuernas de nuevo hacia arriba hasta la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0308-yz9nUhF.gif', '/exercises/images/0308-yz9nUhF.jpg'),
  ('1277', 'dumbbell fly on exercise ball', 'Pecho', 'chest', 'dumbbell', 'pectorals', 'shoulders', ARRAY['shoulders', 'Triceps'], 'Siéntate sobre un balón de estabilidad y sostén una mancuerna en cada mano. Camina con los pies hacia adelante y baja el cuerpo rodando hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón. Extiende los brazos rectos por encima del pecho, con las palmas enfrentadas entre sí. Flexiona ligeramente los codos y baja los brazos hacia los lados describiendo un amplio arco hasta sentir un estiramiento en el pecho. Haz una pausa por un momento, luego invierte el movimiento y contrae los músculos del pecho mientras llevas las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1277-Lt3iWnf.gif', '/exercises/images/1277-Lt3iWnf.jpg'),
  ('0375', 'dumbbell pullover', 'Pecho', 'chest', 'dumbbell', 'pectorals', 'latissimus dorsi', ARRAY['latissimus dorsi', 'Triceps'], 'Túmbate boca arriba en un banco con la cabeza en un extremo y los pies en el suelo. Sujeta una mancuerna con ambas manos y extiende los brazos rectos por encima del pecho. Manteniendo una ligera flexión en los codos, baja lentamente la mancuerna detrás de la cabeza hasta sentir un estiramiento en el pecho y los hombros. Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0375-9XjtHvS.gif', '/exercises/images/0375-9XjtHvS.jpg'),
  ('1294', 'dumbbell pullover hip extension on exercise ball', 'Pecho', 'chest', 'dumbbell', 'pectorals', 'Triceps', ARRAY['Triceps', 'shoulders', 'core'], 'Siéntate sobre un balón de estabilidad con los pies planos en el suelo y la mancuerna apoyada sobre los muslos. Camina lentamente hacia adelante con los pies, haciendo rodar el balón de estabilidad por tu espalda hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón. Sujeta la mancuerna con ambas manos y extiende los brazos rectos por encima del pecho, manteniendo una ligera flexión en los codos. Baja la mancuerna detrás de la cabeza, manteniendo los brazos rectos y con control total. Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial. Manteniendo los brazos extendidos, levanta las caderas del suelo, apretando los glúteos y activando el core. Baja las caderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1294-lI7easp.gif', '/exercises/images/1294-lI7easp.jpg'),
  ('1295', 'dumbbell pullover on exercise ball', 'Pecho', 'chest', 'dumbbell', 'pectorals', 'Triceps', ARRAY['Triceps', 'latissimus dorsi'], 'Siéntate sobre un balón de estabilidad y sujeta una mancuerna con ambas manos por encima del pecho, con los brazos extendidos. Baja lentamente la mancuerna detrás de la cabeza manteniendo los brazos rectos. Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1295-FSD6PGL.gif', '/exercises/images/1295-FSD6PGL.jpg'),
  ('3293', 'archer pull up', 'Espalda', 'back', 'body weight', 'lats', 'Biceps', ARRAY['Biceps', 'Antebrazos'], 'Comienza colgándote de una barra de dominadas con un agarre prono, un poco más separado que el ancho de los hombros. Activa el core y lleva los omóplatos hacia abajo y atrás. Mientras te elevas, flexiona un brazo y lleva el codo hacia el costado, manteniendo el otro brazo recto. Continúa subiendo hasta que la barbilla quede por encima de la barra y el brazo flexionado esté completamente doblado. Bájate de nuevo con control, estirando el brazo flexionado y repitiendo el movimiento del otro lado. Alterna los lados en cada repetición.', '/exercises/gifs/3293-72BC5Za.gif', '/exercises/images/3293-72BC5Za.jpg'),
  ('0027', 'barbell bent over row', 'Espalda', 'back', 'barbell', 'upper back', 'Biceps', ARRAY['Biceps', 'Antebrazos'], 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Inclínate hacia delante desde las caderas manteniendo la espalda recta y el pecho elevado. Agarra la barra con un agarre pronado, con las manos un poco más separadas que el ancho de los hombros. Tira de la barra hacia la parte inferior del pecho retrayendo los omóplatos y contrayendo los músculos de la espalda. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0027-eZyBC3j.gif', '/exercises/images/0027-eZyBC3j.jpg'),
  ('0095', 'barbell shrug', 'Espalda', 'back', 'barbell', 'traps', 'shoulders', ARRAY['shoulders'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra frente a ti con un agarre pronado. Mantén los brazos rectos y la espalda recta durante todo el ejercicio. Levanta los hombros hacia las orejas lo más alto posible, apretando los trapecios en la parte alta. Mantén la posición por un momento y luego baja lentamente los hombros de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0095-dG7tG5y.gif', '/exercises/images/0095-dG7tG5y.jpg'),
  ('2330', 'cable lat pulldown full range of motion', 'Espalda', 'back', 'cable', 'lats', 'Biceps', ARRAY['Biceps', 'rhomboids', 'rear deltoids'], 'Siéntate en la máquina de jalón al pecho con las rodillas colocadas debajo de las almohadillas. Sujeta la barra del cable con un agarre prono, un poco más separado que el ancho de los hombros. Inclínate ligeramente hacia atrás y mantén el pecho elevado, conservando un ligero arco en la zona lumbar. Jala la barra hacia la parte superior del pecho, apretando los omóplatos entre sí. Haz una pausa por un momento en la parte baja del movimiento y luego suelta lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/2330-LEprlgG.gif', '/exercises/images/2330-LEprlgG.jpg'),
  ('0406', 'dumbbell shrug', 'Espalda', 'back', 'dumbbell', 'traps', 'shoulders', ARRAY['shoulders'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano con las palmas hacia tu cuerpo. Mantén los brazos rectos y deja que las mancuernas cuelguen a tus costados. Eleva los hombros lo más alto posible, como si intentaras tocarte las orejas con ellos. Mantén la contracción durante un segundo, luego baja lentamente los hombros de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0406-NJzBsGJ.gif', '/exercises/images/0406-NJzBsGJ.jpg'),
  ('3664', 'dumbbell side plank with rear fly', 'Espalda', 'back', 'dumbbell', 'upper back', 'shoulders', ARRAY['shoulders', 'core'], 'Comienza tumbado de lado con las piernas extendidas y apiladas una sobre la otra. Coloca el antebrazo en el suelo, justo debajo del hombro, manteniendo el codo flexionado en un ángulo de 90 grados. Sujeta una mancuerna con la mano de arriba, con el brazo extendido recto hacia el suelo. Activa el core y levanta las caderas del suelo, formando una línea recta desde la cabeza hasta los talones. Manteniendo la posición de plancha lateral, levanta la mancuerna hacia el techo, apretando los omóplatos entre sí. Baja la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', '/exercises/gifs/3664-X6ytgYZ.gif', '/exercises/images/3664-X6ytgYZ.jpg'),
  ('0651', 'pull up (neutral grip)', 'Espalda', 'back', 'body weight', 'lats', 'Biceps', ARRAY['Biceps', 'Antebrazos'], 'Cuélgate de una barra de dominadas con un agarre neutro (las palmas enfrentadas) y los brazos completamente extendidos. Activa el core y junta los omóplatos. Tira de tu cuerpo hacia la barra flexionando los codos y llevándolos hacia las caderas. Continúa subiendo hasta que la barbilla quede por encima de la barra. Haz una pausa por un momento en la parte alta y luego baja lentamente tu cuerpo, con control, hasta la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0651-0V2YQjW.gif', '/exercises/images/0651-0V2YQjW.jpg'),
  ('0032', 'barbell deadlift', 'Pierna', 'upper legs', 'barbell', 'glutes', 'Isquiotibiales', ARRAY['Isquiotibiales', 'Espalda baja'], 'Ponte de pie con los pies separados a la altura de los hombros y la barra en el suelo frente a ti. Flexiona las rodillas y las caderas para bajar el torso y agarra la barra con un agarre pronado, con las manos un poco más separadas que el ancho de los hombros. Mantén la espalda recta y el pecho elevado mientras empujas con los talones para levantar la barra del suelo, extendiendo las caderas y las rodillas. Al ponerte de pie, aprieta los glúteos y mantén el core activado. Baja la barra de vuelta al suelo flexionando las caderas y las rodillas, manteniendo la espalda recta. Repite el número de repeticiones deseado.', '/exercises/gifs/0032-ila4NZS.gif', '/exercises/images/0032-ila4NZS.jpg'),
  ('0043', 'barbell full squat', 'Pierna', 'upper legs', 'barbell', 'glutes', 'Cuadriceps', ARRAY['Cuadriceps', 'Isquiotibiales', 'Pantorrillas', 'core'], 'Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera. Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios o los deltoides posteriores. Activa el core y mantén el pecho elevado mientras comienzas a bajar el cuerpo. Flexiona las rodillas y las caderas, empujando las caderas hacia atrás y hacia abajo como si te sentaras en una silla. Baja hasta que los muslos queden paralelos al suelo o un poco por debajo. Mantén las rodillas alineadas con los dedos de los pies y el peso sobre los talones. Empuja con los talones para volver a ponerte de pie, extendiendo las caderas y las rodillas. Repite el número de repeticiones deseado.', '/exercises/gifs/0043-qXTaZnJ.gif', '/exercises/images/0043-qXTaZnJ.jpg'),
  ('1461', 'barbell full squat (back pov)', 'Pierna', 'upper legs', 'barbell', 'glutes', 'Cuadriceps', ARRAY['Cuadriceps', 'Isquiotibiales', 'Pantorrillas', 'core'], 'Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera. Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios o los deltoides posteriores. Activa el core y mantén el pecho elevado mientras comienzas a bajar el cuerpo. Flexiona las rodillas y las caderas, empujando las caderas hacia atrás y hacia abajo como si te sentaras en una silla. Baja el cuerpo hasta que los muslos queden paralelos al suelo o un poco por debajo. Mantén las rodillas alineadas con los dedos de los pies y el peso sobre los talones. Empuja con los talones para volver a ponerte de pie, extendiendo las caderas y las rodillas. Repite el número de repeticiones deseado.', '/exercises/gifs/1461-DhMl549.gif', '/exercises/images/1461-DhMl549.jpg'),
  ('1462', 'barbell full squat (side pov)', 'Pierna', 'upper legs', 'barbell', 'glutes', 'Cuadriceps', ARRAY['Cuadriceps', 'Isquiotibiales', 'Pantorrillas', 'core'], 'Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera. Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios o los deltoides posteriores. Activa el core y mantén el pecho elevado mientras comienzas a bajar el cuerpo. Flexiona las rodillas y las caderas, empujando las caderas hacia atrás y hacia abajo como si te sentaras en una silla. Baja el cuerpo hasta que los muslos queden paralelos al suelo o un poco por debajo. Mantén las rodillas alineadas con los dedos de los pies y el peso sobre los talones. Empuja con los talones para volver a ponerte de pie, extendiendo las caderas y las rodillas. Repite el número de repeticiones deseado.', '/exercises/gifs/1462-iYzB0Cz.gif', '/exercises/images/1462-iYzB0Cz.jpg'),
  ('0085', 'barbell romanian deadlift', 'Pierna', 'upper legs', 'barbell', 'glutes', 'Isquiotibiales', ARRAY['Isquiotibiales', 'Espalda baja'], 'Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies apuntando hacia delante. Sujeta la barra con un agarre pronado, manos un poco más separadas que el ancho de los hombros. Flexiona las caderas, manteniendo la espalda recta y las rodillas ligeramente flexionadas. Baja la barra hacia el suelo, manteniéndola cerca del cuerpo. Siente el estiramiento en los isquiotibiales mientras bajas la barra. Cuando sientas el estiramiento en los isquiotibiales, empuja las caderas hacia delante y ponte de pie. Aprieta los glúteos en la parte alta del movimiento. Baja la barra de vuelta a la posición inicial y repite el número de repeticiones deseado.', '/exercises/gifs/0085-wQ2c4XD.gif', '/exercises/images/0085-wQ2c4XD.jpg'),
  ('3235', 'cable assisted inverse leg curl', 'Pierna', 'upper legs', 'cable', 'hamstrings', 'Gluteos', ARRAY['Gluteos', 'Pantorrillas'], 'Ajusta la máquina de cable de modo que el accesorio para el tobillo quede en la posición más baja. Túmbate boca abajo en el banco con las piernas rectas y el accesorio para el tobillo sujeto a los tobillos. Sujétate de las agarraderas del banco para mantener la estabilidad. Manteniendo quieta la parte superior del cuerpo, exhala y flexiona las piernas hacia los glúteos doblando las rodillas. Haz una pausa breve en la parte más alta del movimiento, contrayendo los isquiotibiales. Inhala y baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/3235-zHEpuuc.gif', '/exercises/images/3235-zHEpuuc.jpg'),
  ('1459', 'dumbbell romanian deadlift', 'Pierna', 'upper legs', 'dumbbell', 'glutes', 'Isquiotibiales', ARRAY['Isquiotibiales', 'Espalda baja'], 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono. Manteniendo la espalda recta y el core activado, inclínate desde las caderas y baja las mancuernas hacia el suelo, permitiendo que las rodillas se flexionen ligeramente. Baja las mancuernas hasta sentir un estiramiento en los isquiotibiales, luego empuja con los talones y activa los glúteos para volver a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1459-rR0LJzx.gif', '/exercises/images/1459-rR0LJzx.jpg'),
  ('0496', 'inverse leg curl (bench support)', 'Pierna', 'upper legs', 'body weight', 'hamstrings', 'Gluteos', ARRAY['Gluteos', 'Pantorrillas'], 'Túmbate boca abajo en un banco con las caderas en el borde y las piernas extendidas rectas detrás de ti. Sujétate del banco para mayor apoyo. Manteniendo la parte superior del cuerpo quieta, dobla las rodillas y curva las piernas hacia los glúteos. Haz una pausa breve en la parte superior, luego extiende lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0496-ms7tjSG.gif', '/exercises/images/0496-ms7tjSG.jpg'),
  ('0310', 'dumbbell front raise', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'Biceps', ARRAY['Biceps', 'trapezius'], 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano con las palmas hacia los muslos. Manteniendo los brazos rectos, exhala y levanta las mancuernas frente a ti hasta que queden a la altura de los hombros. Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0310-3eGE2JC.gif', '/exercises/images/0310-3eGE2JC.jpg'),
  ('0309', 'dumbbell front raise v. 2', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'trapezius', ARRAY['trapezius', 'Biceps'], 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano con las palmas hacia los muslos. Mantén la espalda recta y activa el core. Levanta lentamente las mancuernas frente a ti, con los brazos rectos, hasta que queden a la altura de los hombros. Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0309-Rr7S3yg.gif', '/exercises/images/0309-Rr7S3yg.jpg'),
  ('0334', 'dumbbell lateral raise', 'Hombro', 'shoulders', 'dumbbell', 'delts', 'Trapecios', ARRAY['Trapecios'], 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano, con las palmas hacia el cuerpo. Mantén la espalda recta y activa el core. Levanta los brazos hacia los lados hasta que queden paralelos al suelo, manteniendo una ligera flexión en los codos. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0334-DsgkuIt.gif', '/exercises/images/0334-DsgkuIt.jpg'),
  ('0977', 'band front lateral raise', 'Hombro', 'shoulders', 'band', 'delts', 'Trapecios', ARRAY['Trapecios', 'upper back'], 'Ponte de pie con los pies separados a la altura de los hombros y sostén la banda frente a los muslos con las palmas hacia abajo. Mantén los brazos rectos y levanta la banda frente a ti hasta que los brazos queden paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente la banda de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0977-sTg7iys.gif', '/exercises/images/0977-sTg7iys.jpg'),
  ('0978', 'band front raise', 'Hombro', 'shoulders', 'band', 'delts', 'Triceps', ARRAY['Triceps', 'upper back'], 'Ponte de pie con los pies separados a la altura de los hombros y sostén la banda frente a los muslos con las palmas hacia abajo. Mantén los brazos rectos y levántalos lentamente hacia adelante hasta que queden paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0978-TFA88iB.gif', '/exercises/images/0978-TFA88iB.jpg'),
  ('0993', 'band reverse fly', 'Hombro', 'shoulders', 'band', 'delts', 'upper back', ARRAY['upper back', 'trapezius'], 'Sujeta la banda a un objeto fijo a la altura del pecho. Ponte de pie con los pies separados a la altura de los hombros y sostén la banda con ambas manos frente a ti. Mantén los brazos rectos y levántalos hacia los lados hasta que queden paralelos al suelo. Junta los omóplatos en la parte superior del movimiento. Baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0993-sTfvVsG.gif', '/exercises/images/0993-sTfvVsG.jpg'),
  ('0031', 'barbell curl', 'Brazo', 'upper arms', 'barbell', 'biceps', 'Antebrazos', ARRAY['Antebrazos'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre supino, con las palmas mirando hacia delante. Mantén los codos cerca del torso y exhala mientras levantas el peso contrayendo los bíceps. Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala mientras comienzas a bajar lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0031-25GPyDY.gif', '/exercises/images/0031-25GPyDY.jpg'),
  ('1719', 'barbell incline close grip bench press', 'Brazo', 'upper arms', 'barbell', 'triceps', 'chest', ARRAY['chest', 'shoulders'], 'Coloca un banco inclinado a un ángulo de 45 grados. Túmbate en el banco con los pies planos sobre el suelo. Agarra la barra con un agarre cerrado, un poco más estrecho que el ancho de los hombros. Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos cerca del cuerpo. Haz una pausa breve cuando la barra toque el pecho. Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/1719-gx7s7uF.gif', '/exercises/images/1719-gx7s7uF.jpg'),
  ('0059', 'barbell lying preacher curl', 'Brazo', 'upper arms', 'barbell', 'biceps', 'Antebrazos', ARRAY['Antebrazos'], 'Siéntate en un banco predicador con el pecho apoyado en el respaldo y los brazos extendidos sobre el borde, sujetando una barra con un agarre supino. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0059-SYJ4Bkt.gif', '/exercises/images/0059-SYJ4Bkt.jpg'),
  ('0070', 'barbell preacher curl', 'Brazo', 'upper arms', 'barbell', 'biceps', 'Antebrazos', ARRAY['Antebrazos'], 'Siéntate en un banco predicador con los brazos superiores apoyados en el cojín y el pecho contra el soporte. Agarra la barra con un agarre supino, un poco más ancho que la separación de los hombros. Manteniendo los brazos superiores fijos, exhala y levanta la barra hacia los hombros. Haz una pausa breve en la parte alta, apretando los bíceps. Inhala y baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0070-qOgPVf6.gif', '/exercises/images/0070-qOgPVf6.jpg'),
  ('0081', 'barbell reverse preacher curl', 'Brazo', 'upper arms', 'barbell', 'biceps', 'Antebrazos', ARRAY['Antebrazos'], 'Siéntate en un banco predicador con el pecho apoyado en el cojín y los brazos extendidos rectos hacia abajo, sujetando una barra con un agarre pronado. Manteniendo los brazos superiores fijos, exhala y levanta la barra hacia arriba mientras contraes los bíceps. Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0081-4LIG9xr.gif', '/exercises/images/0081-4LIG9xr.jpg'),
  ('0092', 'barbell seated overhead triceps extension', 'Brazo', 'upper arms', 'barbell', 'triceps', 'shoulders', ARRAY['shoulders'], 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros, y levántala por encima de la cabeza. Baja la barra detrás de la cabeza flexionando los codos, manteniendo los brazos superiores cerca de la cabeza. Haz una pausa breve y luego extiende los brazos para levantar la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0092-5uFK1xr.gif', '/exercises/images/0092-5uFK1xr.jpg'),
  ('0109', 'barbell standing overhead triceps extension', 'Brazo', 'upper arms', 'barbell', 'triceps', 'shoulders', ARRAY['shoulders'], 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono. Levanta la barra por encima de la cabeza, extendiendo completamente los brazos. Manteniendo los brazos superiores cerca de la cabeza, baja lentamente la barra detrás de la cabeza flexionando los codos. Haz una pausa breve, luego levanta la barra de vuelta a la posición inicial extendiendo los brazos. Repite el número de repeticiones deseado.', '/exercises/gifs/0109-dZl9Q27.gif', '/exercises/images/0109-dZl9Q27.jpg'),
  ('0165', 'cable hammer curl (with rope)', 'Brazo', 'upper arms', 'cable', 'biceps', 'Antebrazos', ARRAY['Antebrazos'], 'Ponte de pie con los pies separados a la altura de los hombros y una ligera flexión en las rodillas. Sujeta el accesorio de cuerda del cable con agarre supino, palmas mirándose entre sí, y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando el accesorio de cuerda del cable hasta que los bíceps estén completamente contraídos y la cuerda esté a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente el accesorio de cuerda del cable de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0165-HPlPoQA.gif', '/exercises/images/0165-HPlPoQA.jpg'),
  ('0014', 'assisted motion russian twist', 'Core', 'waist', 'medicine ball', 'abs', 'Oblicuos', ARRAY['Oblicuos', 'Espalda baja'], 'Siéntate en el suelo con las rodillas flexionadas y los pies apoyados en el suelo. Sostén el balón medicinal con ambas manos frente al pecho. Inclínate ligeramente hacia atrás, activando el abdomen y manteniendo la espalda recta. Gira lentamente el torso hacia la derecha, llevando el balón medicinal hacia el lado derecho del cuerpo. Haz una pausa por un momento, luego gira el torso hacia la izquierda, llevando el balón medicinal hacia el lado izquierdo del cuerpo. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/0014-r7cT9YD.gif', '/exercises/images/0014-r7cT9YD.jpg'),
  ('3544', 'bodyweight incline side plank', 'Core', 'waist', 'body weight', 'abs', 'Oblicuos', ARRAY['Oblicuos', 'shoulders'], 'Comienza tumbado de lado con las piernas extendidas y apiladas una sobre la otra. Coloca el antebrazo en el suelo justo debajo del hombro, con el codo flexionado en un ángulo de 90 grados. Activa el core y levanta las caderas del suelo, formando una línea recta desde la cabeza hasta los pies. Mantén esta posición durante el tiempo deseado. Baja las caderas de nuevo al suelo y repite hacia el otro lado.', '/exercises/gifs/3544-5VXmnV5.gif', '/exercises/images/3544-5VXmnV5.jpg'),
  ('0211', 'cable russian twists (on stability ball)', 'Core', 'waist', 'cable', 'abs', 'Oblicuos', ARRAY['Oblicuos', 'Espalda baja'], 'Siéntate sobre un balón de estabilidad con los pies apoyados planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Sujeta la agarradera del cable con ambas manos y extiende los brazos rectos frente a ti. Inclínate ligeramente hacia atrás manteniendo la espalda recta y el core activado. Gira el torso hacia la derecha, llevando la agarradera del cable hacia la cadera derecha. Haz una pausa por un momento y luego gira el torso hacia la izquierda, llevando la agarradera del cable hacia la cadera izquierda. Continúa alternando los giros el número de repeticiones deseado.', '/exercises/gifs/0211-d9Xaxq6.gif', '/exercises/images/0211-d9Xaxq6.jpg'),
  ('0276', 'dead bug', 'Core', 'waist', 'body weight', 'abs', 'Flexores de cadera', ARRAY['Flexores de cadera', 'Espalda baja'], 'Túmbate boca arriba con los brazos extendidos hacia el techo. Flexiona las rodillas y levanta las piernas del suelo, formando un ángulo de 90 grados en las caderas y las rodillas. Activa el core y la zona lumbar para presionar la zona lumbar contra el suelo. Baja lentamente el brazo derecho y la pierna izquierda hacia el suelo, manteniéndolos rectos y justo por encima del suelo. Haz una pausa breve y luego vuelve a la posición inicial. Repite el movimiento con el brazo izquierdo y la pierna derecha. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/0276-iny3m5y.gif', '/exercises/images/0276-iny3m5y.jpg'),
  ('0464', 'front plank with twist', 'Core', 'waist', 'body weight', 'abs', 'Oblicuos', ARRAY['Oblicuos', 'shoulders'], 'Comienza en posición de plancha alta con las manos directamente debajo de los hombros y el cuerpo en línea recta de la cabeza a los pies. Activa el core y los glúteos para mantener una posición estable. Gira el torso hacia la derecha, levantando el brazo derecho y extendiéndolo hacia el techo. Mantén las caderas y las piernas estables mientras giras. Mantén la posición por un momento, luego regresa a la posición inicial. Repite el giro hacia el lado izquierdo. Continúa alternando lados durante el número de repeticiones deseado.', '/exercises/gifs/0464-CosupLu.gif', '/exercises/images/0464-CosupLu.jpg'),
  ('0472', 'hanging leg raise', 'Core', 'waist', 'body weight', 'abs', 'Flexores de cadera', ARRAY['Flexores de cadera'], 'Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera. Activa el core y levanta las piernas frente a ti, manteniéndolas rectas. Continúa levantando hasta que las piernas estén paralelas al suelo o tan alto como puedas llegar cómodamente. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0472-I3tsCnC.gif', '/exercises/images/0472-I3tsCnC.jpg'),
  ('0088', 'barbell seated calf raise', 'Pantorrilla', 'lower legs', 'barbell', 'calves', 'Isquiotibiales', ARRAY['Isquiotibiales', 'Cuadriceps'], 'Siéntate en un banco con los pies planos sobre el suelo y una barra apoyada sobre los muslos. Coloca la parte delantera de los pies sobre una plataforma elevada, como un bloque o un escalón. Coloca la barra sobre los muslos y sujétala con firmeza con las manos. Manteniendo la espalda recta y el core activado, levanta los talones del suelo extendiendo los tobillos. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0088-ktsFQAZ.gif', '/exercises/images/0088-ktsFQAZ.jpg'),
  ('1371', 'barbell seated calf raise', 'Pantorrilla', 'lower legs', 'barbell', 'calves', 'Isquiotibiales', ARRAY['Isquiotibiales'], 'Siéntate en un banco con los pies planos sobre el suelo y una barra apoyada sobre los muslos. Coloca la parte delantera de los pies sobre una plataforma elevada, como un bloque o un escalón. Baja los talones tanto como sea posible, sintiendo un estiramiento en las pantorrillas. Levanta los talones lo más alto posible, contrayendo las pantorrillas. Repite el número de repeticiones deseado.', '/exercises/gifs/1371-ipvgBnC.gif', '/exercises/images/1371-ipvgBnC.jpg'),
  ('1372', 'barbell standing calf raise', 'Pantorrilla', 'lower legs', 'barbell', 'calves', 'Isquiotibiales', ARRAY['Isquiotibiales', 'Gluteos'], 'Ponte de pie con los pies separados a la altura de los hombros y coloca una barra sobre la parte superior de la espalda. Levanta los talones del suelo lo más alto posible, apoyándote solo en las puntas de los pies. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/1372-8ozhUIZ.gif', '/exercises/images/1372-8ozhUIZ.jpg'),
  ('0126', 'barbell wrist curl', 'Antebrazo', 'lower arms', 'barbell', 'forearms', 'Biceps', ARRAY['Biceps', 'brachialis'], 'Siéntate en un banco con los pies planos en el suelo y los antebrazos apoyados sobre los muslos, sujetando una barra con agarre supino. Deja que la barra ruede hacia las puntas de los dedos, manteniendo las muñecas rectas. Enrolla lentamente la barra hacia los antebrazos flexionando las muñecas. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0126-82LxxkW.gif', '/exercises/images/0126-82LxxkW.jpg'),
  ('0125', 'barbell wrist curl v. 2', 'Antebrazo', 'lower arms', 'barbell', 'forearms', 'Biceps', ARRAY['Biceps', 'brachialis'], 'Siéntate en un banco con los pies planos sobre el suelo y las rodillas flexionadas. Sujeta una barra con agarre supino, palmas hacia arriba, y las manos separadas a la altura de los hombros. Apoya los antebrazos sobre los muslos, dejando que las muñecas cuelguen del borde. Flexiona lentamente las muñecas hacia arriba, llevando la barra hacia los antebrazos. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', '/exercises/gifs/0125-6kSxYnw.gif', '/exercises/images/0125-6kSxYnw.jpg'),
  ('1160', 'burpee', 'Cardio', 'cardio', 'body weight', 'cardiovascular system', 'Cuadriceps', ARRAY['Cuadriceps', 'Isquiotibiales', 'Pantorrillas', 'shoulders', 'chest'], 'Comienza de pie con los pies separados a la altura de los hombros. Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y colocando las manos en el suelo frente a ti. Lleva los pies hacia atrás de una patada hasta una posición de flexión de brazos. Realiza una flexión de brazos, manteniendo el cuerpo en línea recta. Salta con los pies de vuelta a la posición de sentadilla. Salta hacia arriba explosivamente, llevando los brazos por encima de la cabeza. Aterriza suavemente y baja de inmediato a una posición de sentadilla para comenzar la siguiente repetición.', '/exercises/gifs/1160-dK9394r.gif', '/exercises/images/1160-dK9394r.jpg'),
  ('2612', 'jump rope', 'Cardio', 'cardio', 'rope', 'cardiovascular system', 'Pantorrillas', ARRAY['Pantorrillas', 'Cuadriceps', 'Isquiotibiales', 'Gluteos'], 'Sujeta las asas de la cuerda de saltar con las manos, palmas hacia adentro. Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Balancea la cuerda por encima de la cabeza y salta sobre ella cuando se acerque a los pies. Aterriza suavemente sobre la punta de los pies y repite el salto cuando la cuerda vuelva a pasar. Continúa saltando durante el tiempo o el número de repeticiones deseado.', '/exercises/gifs/2612-e1e76I2.gif', '/exercises/images/2612-e1e76I2.jpg'),
  ('1403', 'neck side stretch', 'Cuello', 'neck', 'body weight', 'levator scapulae', 'trapezius', ARRAY['trapezius', 'sternocleidomastoid'], 'Ponte de pie o siéntate erguido con los hombros relajados. Inclina la cabeza hacia un lado, llevando la oreja hacia el hombro. Mantén el estiramiento durante 15-30 segundos. Repite del otro lado. Realiza de 2 a 4 series por cada lado.', '/exercises/gifs/1403-x2chWLO.gif', '/exercises/images/1403-x2chWLO.jpg')
